for sequence in (ML,DA):
 sequence[7]['explain'] += ' Assigning a new column name creates a calculated column: sales["double_units"] = sales["units"] * 2 doubles each row. Multiplying two numerical columns instead multiplies corresponding rows. This is how units times unit price becomes revenue.'
 sequence[7]['demo'] += '\nsales["double_units"] = sales["units"] * 2\nprint(sales["double_units"])'
 sequence[7]['expected'] += ' The added double_units column is 4, 10, 6 in row order.'
 sequence[10]['explain'] += ' A grouped pandas result has index labels and values: totals.index contains category names and totals.values contains the numbers. Pass them to plt.bar(totals.index, totals.values) to chart a grouped table.'
